import fs from 'node:fs'

const ADR_PATH = 'docs/decisiones/0031-cuentas-controladas-y-comprobaciones.md'
const IMG_PATH = 'docs/capturas/12-comprobaciones.png'
const ADR = "# ADR 0031 · Cuentas controladas (modo estricto o guiado) y comprobaciones del auditor\n\n- **Fecha:** 2026-10-15\n- **Versión:** v0.33.0\n- **Estado:** aceptada\n\n## Contexto\n\nCon la v0.32.0 los pagos ya se hacen contra la factura, pero nada impedía seguir haciéndolos a mano («410 a 572»):\nla factura no se enteraba y la cuenta del tercero dejaba de cuadrar con sus facturas. Los ERP resuelven esto de dos\nmaneras:\n\n- **SAP y Business Central controlan «antes».** La cuenta de proveedores es una *cuenta asociada* (SAP) o no admite\n  *registro directo* (BC): solo la mueve su módulo. En el ERP cubano Versat eran las «cuentas controladas».\n- **Los ERP españoles (A3, Sage, ContaPlus) controlan «después».** Dejan el asiento manual y lo detectan con cuadres:\n  el IVA contra el libro registro, los terceros contra sus facturas, el punteo…\n\nPara un laboratorio de aprendizaje interesan las dos: la disciplina de SAP/BC y los cuadres que hace un auditor en\nEspaña (`docs/cuentas-controladas.md`).\n\n## Decisión\n\n1. **Cuentas controladas como datos** (`erp.control_rules`, migración 0036): qué módulo mueve cada cuenta y por qué\n   lado. Gana el prefijo más largo.\n\n   | Cuentas | Lado | La mueven |\n   |---|---|---|\n   | 400, 410, 430, 440 | ambos | Facturas y Cobros y pagos |\n   | 4009, 4309 | — | libres (ajustes de cierre) |\n   | 472, 477 | ambos | Facturas y Liquidación |\n   | 4750 | Haber | Liquidación (el pago a Hacienda, al Debe, es manual) |\n   | 4700 | Debe | Liquidación (el cobro de la devolución, al Haber, es manual) |\n2. **Modo por empresa** (`companies.control_mode`, solo lo cambia el administrador):\n   - **estricto** (SAP/BC): un asiento manual que mueve una cuenta controlada no se contabiliza. Se comprueba con un\n     trigger de restricción **diferido** al final de la transacción, porque los módulos crean primero el asiento y\n     después su documento;\n   - **guiado** (ERP español): se contabiliza, la web avisa antes y queda listado en Comprobaciones;\n   - por defecto, guiado en la base de datos (no cambia nada en las empresas existentes ni en las importadas); la web\n     crea las empresas nuevas en estricto;\n   - nunca se bloquean la apertura, el cierre, los contraasientos, las importaciones ni los asientos de los módulos.\n3. **Comprobaciones del auditor como datos** (`erp.audit_checks`, `erp.run_audit_checks`, migración 0037), siempre\n   activas y a una fecha. Cada una da el libro, la contabilidad, la diferencia, los casos enlazados y la pantalla donde\n   se arregla:\n   - 472 y 477 frente al libro registro (sin liquidación ni prorrata);\n   - 4751 frente a los modelos 111/115. Es informativa: las retenciones de nómina son normales;\n   - cada tercero frente a sus facturas pendientes;\n   - saldos al revés de su naturaleza (reutiliza la 0013): aviso, o error si es imposible;\n   - IGIC en la Península o IVA en Canarias;\n   - asientos manuales sobre cuentas controladas (los pagos ya vinculados no cuentan).\n4. **Conceptos** (`erp.concepts`, migración 0038): el glosario también en la base de datos, con las cuentas del PGC de\n   cada término. Es la primera pieza de la ontología: cuenta → conceptos → comprobaciones, para el Tutor y el chat.\n   La fuente sigue siendo `glossary.js`, porque la web lo enseña sin sesión y al instante; un test falla si las dos\n   copias se separan.\n5. **Web:**\n   - modo de control al crear la empresa y en la pantalla Comprobaciones;\n   - aviso en el formulario de asiento antes de contabilizar, y en estricto no se puede contabilizar, solo guardar en\n     borrador;\n   - error traducido con un botón a la pantalla del módulo;\n   - pantalla «Comprobaciones» en el menú Auditor;\n   - cuentas del PGC en el glosario, que también se busca por cuenta.\n\n## Alternativas descartadas\n- **Solo avisar (sin modo estricto):** no enseña la disciplina de SAP/BC, que es justo lo que pide el mercado.\n- **Solo bloquear:** rompería la contabilidad importada y no enseña los cuadres de un auditor español.\n- **Una marca por subcuenta** en `gl_accounts`: duplicaría la regla en cada empresa. Por prefijo y como datos se\n  cambia en un sitio.\n- **La web lee el glosario de la base de datos:** habría que abrir la tabla a anónimos y esperar una consulta para\n  cada globo ⓘ.\n\n## Consecuencias\n- El ERP se comporta como SAP/BC o como un ERP español con un interruptor, y el alumno ve la diferencia.\n- Las comprobaciones son la base de la fase 3 del plan «IA guiada por reglas»: el chat podrá responder «¿cuadra mi\n  IVA?» con datos, no con suposiciones.\n- **Pruebas:** 32 de 32 en la base de datos (fases 30, 31 y 32 nuevas) y 98 tests de la web.\n"
const CHANGELOG = "## [0.33.0] - 2026-10-15\n### Añadido\n- **Cuentas controladas** (como SAP, Business Central o Versat):\n  - reglas por prefijo en la base de datos (400/410/430/440, 472/477, 4750, 4700);\n  - **modo estricto o guiado** por empresa;\n  - en estricto, un asiento manual sobre esas cuentas no se contabiliza;\n  - migración `0036_controlled_accounts.sql` y prueba `test_fase30_controlled_accounts.sql`.\n- **Comprobaciones del auditor** a una fecha: 472/477 frente al libro registro, 4751 frente al 111/115, terceros\n  frente a sus facturas, saldos anómalos, impuesto del otro territorio y asientos manuales sobre cuentas controladas.\n  Migración `0037_audit_checks.sql` y prueba `test_fase31_audit_checks.sql`.\n- Pantalla **Comprobaciones** (menú Auditor) con el modo de control, cifras, casos enlazados y la pantalla donde se\n  arregla.\n- **Aviso en el formulario de asiento** antes de contabilizar sobre una cuenta controlada, y error traducido con\n  enlace a su módulo.\n- **Conceptos** en la base de datos (`erp.concepts`), con sus cuentas del PGC: migración `0038_concepts.sql` y prueba\n  `test_fase32_concepts.sql`.\n- Glosario: 4 términos nuevos (cuenta controlada, modo estricto o guiado, antigüedad de saldos, comprobación) y las\n  cuentas del PGC de cada término; el buscador encuentra por cuenta.\n- `src/controlled.js` con sus tests, y `tests/glossary.test.js`, que falla si el glosario y `erp.concepts` se separan\n  (98 tests en total).\n### Cambiado\n- Las empresas nuevas se crean en modo estricto (se elige al darlas de alta); las existentes y las importadas siguen\n  en guiado.\n### Corregido\n- Contraste del «✓ Cuadra» de los totales del asiento (WCAG AA).\n"
const BITACORA = "\n## 2026-10-15 · v0.33.0 · Cuentas controladas y comprobaciones del auditor\n\n**Qué se hizo**\n- **Cuentas controladas** con un interruptor por empresa (migración 0036):\n  - **estricto** como SAP/BC: un asiento manual sobre la 410, la 430 o la 472 no se contabiliza;\n  - **guiado** como un ERP español: avisa y lo deja revisar.\n- **Comprobaciones del auditor** a una fecha (0037), en una pantalla nueva con el detalle enlazado.\n- **Conceptos**: el glosario también en la base de datos (0038), con sus cuentas del PGC.\n- 32 pruebas SQL (fases 30, 31 y 32 nuevas) y 98 tests de la web.\n\n**Lo que se aprende en esta fase**\n- **Controlar antes o después:**\n  - SAP y BC impiden el error (cuenta asociada, sin registro directo);\n  - los ERP españoles lo detectan con cuadres;\n  - un auditor hace estos mismos cuadres en cualquier empresa.\n- **El cuadre del IVA:** la 472/477, sin la liquidación, debe salir entera de las facturas. Lo que sobra es un\n  asiento manual que no está en el libro registro ni en el 303/420.\n- **La 4751 frente al 111:** la retención de un profesional sale de su factura. Una anotada a mano no estará en el\n  resumen, salvo las de nómina, que el ERP aún no gestiona.\n- **Por qué existen las cuentas controladas:** no es burocracia, es que la factura sepa si está pagada y el libro de\n  IVA cuadre con la contabilidad.\n- **Restricciones diferidas en PostgreSQL:** la regla se comprueba al final de la transacción, cuando el documento ya\n  existe (`DEFERRABLE INITIALLY DEFERRED`).\n\n**Decisiones:** ADR 0031 · Cuentas controladas (modo estricto o guiado) y comprobaciones del auditor.\n\n**Siguiente paso:** v0.34.0 · catálogo de operaciones y Tutor «dónde se registra»: la IA clasifica la operación y el\nERP dice en qué pantalla se hace y con qué asiento.\n"
const README = [
  [
    "## ¿Qué hace hoy? (v0.32.0)",
    "## ¿Qué hace hoy? (v0.33.0)"
  ],
  [
    "  movimientos sin vincular. Días de pago del tercero, vencimiento y estado de cada factura.\n",
    "  movimientos sin vincular. Días de pago del tercero, vencimiento y estado de cada factura.\n- **Cuentas controladas** con un interruptor por empresa: **estricto** como SAP o Business Central (un asiento\n  manual sobre la 410, la 430 o la 472 no se contabiliza: se registra desde su pantalla) o **guiado** como los ERP\n  españoles (avisa antes y lo lista después). **Comprobaciones del auditor** a una fecha: IVA/IGIC frente al libro\n  registro, retenciones frente al 111/115, terceros frente a sus facturas, saldos anómalos e impuesto del otro\n  territorio, con cada caso enlazado y la pantalla donde se arregla.\n"
  ],
  [
    "29 pruebas SQL, 89 tests de la web",
    "32 pruebas SQL, 98 tests de la web"
  ],
  [
    "0001 → 0035,",
    "0001 → 0038,"
  ],
  [
    "`database/migrations/0001` … `0035`",
    "`database/migrations/0001` … `0038`"
  ],
  [
    "ADR 0001 → 0030",
    "ADR 0001 → 0031"
  ],
  [
    "las 29 pruebas de la base de datos",
    "las 32 pruebas de la base de datos"
  ],
  [
    "**89 tests de la web con Vitest**",
    "**98 tests de la web con Vitest**"
  ],
  [
    "# las 29 pruebas, cada una en una base limpia",
    "# las 32 pruebas, cada una en una base limpia"
  ],
  [
    "# 89 tests con Vitest",
    "# 98 tests con Vitest"
  ],
  [
    "· [cobros y pagos](docs/capturas/11-cobros-pagos.png)",
    "· [cobros y pagos](docs/capturas/11-cobros-pagos.png) · [comprobaciones](docs/capturas/12-comprobaciones.png)"
  ],
  [
    "- [x] **v0.32.0**: cobros y pagos contra la factura, vencimientos y antigüedad de saldos\n",
    "- [x] **v0.32.0**: cobros y pagos contra la factura, vencimientos y antigüedad de saldos\n- [x] **v0.33.0**: cuentas controladas (modo estricto o guiado) y comprobaciones del auditor\n"
  ]
]
const IMG = ''

let avisos = 0
const leer = (p) => fs.readFileSync(p, 'utf8')
const crlf = (s) => s.includes('\r\n')
const guardar = (p, texto, conCrlf) => fs.writeFileSync(p, conCrlf ? texto.replace(/\r?\n/g, '\r\n') : texto)

if (!fs.existsSync('README.md') || !fs.existsSync('docs')) {
  console.error('✗ Ejecútalo desde la carpeta raíz del proyecto (donde están README.md y docs).'); process.exit(1)
}

if (fs.existsSync(ADR_PATH)) console.log('· ADR 0031 ya existía')
else { fs.writeFileSync(ADR_PATH, ADR); console.log('✓ ' + ADR_PATH) }

if (fs.existsSync(IMG_PATH)) console.log('· La captura ya existía')
else { fs.mkdirSync('docs/capturas', { recursive: true }); fs.writeFileSync(IMG_PATH, Buffer.from(IMG, 'base64')); console.log('✓ ' + IMG_PATH) }

{
  const raw = leer('CHANGELOG.md'), c = crlf(raw), s = raw.replace(/\r\n/g, '\n')
  if (s.includes('## [0.33.0]')) console.log('· CHANGELOG ya tenía la 0.33.0')
  else if (s.includes('## [0.32.0]')) { guardar('CHANGELOG.md', s.replace('## [0.32.0]', CHANGELOG + '\n## [0.32.0]'), c); console.log('✓ CHANGELOG.md') }
  else { avisos++; console.log('⚠ CHANGELOG.md: no encuentro "## [0.32.0]"; pega a mano el texto de la 0.33.0 arriba') }
}

{
  const raw = leer('docs/bitacora.md'), c = crlf(raw), s = raw.replace(/\r\n/g, '\n')
  if (s.includes('· v0.33.0 ·')) console.log('· La bitácora ya tenía la v0.33.0')
  else { guardar('docs/bitacora.md', s.replace(/\n*$/, '\n') + BITACORA, c); console.log('✓ docs/bitacora.md') }
}

{
  const raw = leer('README.md'), c = crlf(raw)
  let s = raw.replace(/\r\n/g, '\n')
  for (const [de, a] of README) {
    if (s.includes(a)) continue
    if (!s.includes(de)) { avisos++; console.log('⚠ README.md: no encuentro «' + de.trim().slice(0, 70) + '»'); continue }
    s = s.replace(de, a)
  }
  guardar('README.md', s, c); console.log('✓ README.md')
}

console.log(avisos ? `\nHecho con ${avisos} aviso(s): revísalos.` : '\n✔ Paso 174 aplicado. Revisa los cambios con: git diff')
